FilterRow.PlainStringOptions:
function Demo() {
  const [selected, setSelected] = useState<string[]>(['admin']);
  return (
    <FilterRow
      label="Role"
      options={['admin', 'manager', 'foreman', 'finance']}
      selected={selected}
      onToggle={v => setSelected(s => (s.includes(v) ? s.filter(x => x !== v) : [...s, v]))}
      onClear={() => setSelected([])}
      capitalize
    />
  );
}
return <Demo />;

